"""Retry wrapper for Meridian CRM integration endpoints."""

from __future__ import annotations


class TransientError(Exception):
    """A retryable transport failure."""


class PermanentError(Exception):
    """A non-retryable transport failure."""


def call_with_retry(endpoint_cfg: dict, transport) -> dict:
    """Invoke an injected transport according to the endpoint retry policy."""
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    retry_count = endpoint_cfg["retry"]

    attempts = 0

    while True:
        attempts += 1
        try:
            result = transport(url, timeout_ms)
        except PermanentError as exc:
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(exc),
                },
            }
        except TransientError as exc:
            if attempts <= retry_count:
                continue
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "transient",
                    "message": str(exc),
                },
            }
        else:
            return {
                "ok": True,
                "attempts": attempts,
                "result": result,
                "error": None,
            }
